n=30
G=[[0]*n for _ in range(n)]
# The framed square occupies rows/cols 1..25. Preserve outer 5 frame;
# add concentric inner frames down to a 3x3 empty center, alternating 2,5.
for r in range(1,26):
    for c in range(1,26):
        if r==1 or r==25 or c==1 or c==25:
            G[r][c]=5
for k in range(2,12):
    color=2 if k%2==0 else 5
    lo=k; hi=26-k
    for c in range(lo,hi+1):
        G[lo][c]=color; G[hi][c]=color
    for r in range(lo,hi+1):
        G[r][lo]=color; G[r][hi]=color
print('{"action":"submit","grid":'+__import__('json').dumps(G,separators=(',',':'))+'}')

